private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; i++) {
        AbstractType type = currentFrame.get(i);
        byte tag = type.getTag(); // tag according to JVMS verification_type_info
        byte[] entry;
        switch (tag) {
            case AbstractType.TOP:
            case AbstractType.INTEGER:
            case AbstractType.FLOAT:
            case AbstractType.LONG:
            case AbstractType.DOUBLE:
            case AbstractType.NULL:
            case AbstractType.UNINITIALIZED_THIS:
                entry = new byte[]{tag};
                break;
            case AbstractType.OBJECT:
                int cpIndex = type.getCpIndex(); // constant pool index for the class
                entry = new byte[]{tag, (byte) ((cpIndex >> 8) & 0xFF), (byte) (cpIndex & 0xFF)};
                break;
            case AbstractType.UNINITIALIZED:
                int offset = type.getOffset(); // offset of the new instruction
                entry = new byte[]{tag, (byte) ((offset >> 8) & 0xFF), (byte) (offset & 0xFF)};
                break;
            default:
                throw new IllegalArgumentException("Unknown verification type tag: " + tag);
        }
        stackMapTableEntries.add(entry);
    }
}

