final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer){
    // The constant pool starts after the 10-byte header (magic, minor, major, constant_pool_count)
    int offset = 10;
    // Skip entries until we reach the desired index
    for (int i = 1; i < constantPoolEntryIndex; i++) {
        int tag = classFileBuffer[offset] & 0xFF;
        offset++;
        switch (tag) {
            case 1: { // CONSTANT_Utf8
                int len = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
                offset += 2 + len;
                break;
            }
            case 3: case 4: case 5: case 6: case 7: case 8: case 9: case 10: case 11: case 12: case 13: case 14: case 15: case 16: case 17: {
                if (tag == 4 || tag == 5) { // long or double take two indices
                    offset += 8;
                    i++; // skip the second index
                } else if (tag == 15) { // MethodHandle: 1 byte kind + 2 bytes reference
                    offset += 3;
                } else if (tag == 16) { // MethodType: 2 bytes descriptor
                    offset += 2;
                } else if (tag == 17) { // InvokeDynamic: 2 bytes bootstrap + 2 bytes name_and_type
                    offset += 4;
                } else {
                    offset += 4; // most other tags are 4 bytes
                }
                break;
            }
            default:
                throw new IllegalArgumentException("Invalid constant pool tag: " + tag);
        }
    }
