            ConstantUtf8_info nameUtf8 = (ConstantUtf8_info) constantPool.get(nt.getNameIndex());
            ConstantUtf8_info descUtf8 = (ConstantUtf8_info) constantPool.get(nt.getDescriptorIndex());
            if (name.equals(nameUtf8.getString()) && descriptor.equals(descUtf8.getString())) {
                return i; // already present
            }
