    while (pos < input.length()) {
        char ch = input.charAt(pos);
        boolean isTerminator = false;
        if (terminators != null) {
            for (char t : terminators) {
                if (ch == t) {
                    isTerminator = true;
                    break;
                }
            }
        }
        if (isTerminator) {
            pos++; // consume the terminator for the next parse
            break;
        }
        sb.append(ch);
        pos++;
    }
    return sb.toString();
}

