private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Create a circulator starting at the given node and in the specified direction.
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

    // Iterate over the nodes on the outer face until we hit the stop node
    // or find a node that satisfies the predicate.
    while (true) {
        Node current = circ.getNode();

        // If we reached the stop node, return the circulator pointing to it.
        if (current == stop) {
            return circ;
        }

        // If the current node satisfies the predicate, return the circulator pointing to it.
        if (predicate.test(current)) {
            return circ;
        }

        // Move to the next node in the traversal direction.
        circ = circ.next();
    }
}

