protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || tour.isEmpty() || graph == null) {
        return null;
    }
    // Build degree map for vertices in the tour
    Map<V,Integer> degree = new HashMap<>();
    for (E e : tour) {
        V u = graph.getEdgeSource(e);
        V v = graph.getEdgeTarget(e);
        degree.put(u, degree.getOrDefault(u, 0) + 1);
        degree.put(v, degree.getOrDefault(v, 0) + 1);
    }
    // Choose a start vertex (prefer degree 1 for a path, otherwise any)
    V start = null;
    for (Map.Entry<V,Integer> entry : degree.entrySet()) {
        if (entry.getValue() == 1 || entry.getValue() == 2) {
            start = entry.getKey();
            break;
        }
    }
    if (start == null) {
        // Fallback: use source of first edge
        start = graph.getEdgeSource(tour.iterator().next());
    }
    List<V> vertexList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();
    Set<E> visited = new HashSet<>();
    vertexList.add(start);
    V current = start;
    while (visited.size() < tour.size()) {
        E nextEdge = null;
        for (E e : tour) {
            if (!visited.contains(e)) {
                V u = graph.getEdgeSource(e);
                V v = graph.getEdgeTarget(e);
                if (u.equals(current) || v.equals(current)) {
                    nextEdge = e;
                    break;
                }
            }
        }
        if (nextEdge == null) {
            break; // disconnected or incomplete tour
        }
        V next = graph.getEdgeSource(nextEdge).equals(current) ?
                 graph.getEdgeTarget(nextEdge) :
                 graph.getEdgeSource(nextEdge);
        vertexList.add(next);
        edgeList.add(nextEdge);
        visited.add(nextEdge);
        current = next;
    }
    // If the tour is a cycle, close it by adding the start vertex at the end
    if (degree.get(start) != null && degree.get(start) == 2) {
        vertexList.add(start);
    }
    double weight = 0.0;
    for (E e : edgeList) {
        weight += graph.getEdgeWeight(e);
    }
    V end = vertexList.get(vertexList.size() - 1);
    return new GraphWalk<>(graph, start, end, vertexList, edgeList, weight);
}

