private List<Integer> computeUpperBounds(List<K> keys){
    java.util.List<Integer> upperBounds = new java.util.ArrayList<>();
    if (keys == null || keys.isEmpty()){
        return upperBounds;
    }
    java.util.List<Integer> hashCodes = new java.util.ArrayList<>(keys.size());
    for (K key : keys){
        hashCodes.add(key == null ? 0 : key.hashCode());
    }
    for (int i = 0; i < hashCodes.size(); i++){
        int current = hashCodes.get(i);
        int max = current;
        for (int j = 0; j < hashCodes.size(); j++){
            int h = hashCodes.get(j);
            if (h >= current && h > max){
                max = h;
            }
        }
        upperBounds.add(max);
    }
    return upperBounds;
}

