            sb.append('\\');
            break;
        }
        char next = input.charAt(i + 1);
        switch (next) {
            case 'n':
                sb.append('\n');
                i++;
                break;
            case 't':
                sb.append('\t');
                i++;
                break;
            case 'r':
                sb.append('\r');
                i++;
                break;
            case 'b':
                sb.append('\b');
                i++;
