public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pt = (ParameterizedType) genericType;
    Type rawType = pt.getRawType();
    if (!(rawType instanceof Class<?>)) {
        return null;
    }
    Class<?> raw = (Class<?>) rawType;
    Deque<Type> stack = new ArrayDeque<>();
    stack.push(targetType);
    while (!stack.isEmpty()) {
        Type t = stack.pop();
        if (t instanceof ParameterizedType) {
            ParameterizedType p = (ParameterizedType) t;
            Class<?> pRaw = (Class<?>) p.getRawType();
            if (pRaw.equals(raw)) {
                Type[] args = p.getActualTypeArguments();
                Class<?>[] result = new Class<?>[args.length];
                for (int i = 0; i < args.length; i++) {
                    Type arg = args[i];
                    if (arg instanceof Class<?>) {
                        result[i] = (Class<?>) arg;
                    } else if (arg instanceof ParameterizedType) {
                        result[i] = (Class<?>) ((ParameterizedType) arg).getRawType();
                    } else {
                        return null;
                    }
                }
                return result;
            }
            for (Type iface : pRaw.getGenericInterfaces()) {
                stack.push(iface);
            }
            Type superT = pRaw.getGenericSuperclass();
            if (superT != null) {
                stack.push(superT);
            }
        } else if (t instanceof Class<?>) {
            Class<?> c = (Class<?>) t;
            if (c.equals(raw)) {
