public static String applyRelativePath(String path, String relativePath) {
    if (path == null) {
        throw new IllegalArgumentException("path cannot be null");
    }
    if (relativePath == null) {
        throw new IllegalArgumentException("relativePath cannot be null");
    }
    java.nio.file.Path base = java.nio.file.Paths.get(path);
    java.nio.file.Path rel = java.nio.file.Paths.get(relativePath);
    java.nio.file.Path resolved = base.resolve(rel).normalize();
    String result = resolved.toString();
    // Ensure the returned path uses '/' as separator regardless of OS
    if (java.io.File.separatorChar != '/') {
        result = result.replace(java.io.File.separatorChar, '/');
    }
    return result;
}

