protected int removeUnusedNodes() {
    if (root == null) {
        return 0;
    }
    int removed = 0;
    if (!root.isActive()) {
        root = null;
        return 1;
    }
    java.util.Deque<Category> stack = new java.util.ArrayDeque<>();
    stack.push(root);
    while (!stack.isEmpty()) {
        Category current = stack.pop();
        java.util.List<Category> children = current.getChildren();
        for (int i = children.size() - 1; i >= 0; i--) {
            Category child = children.get(i);
            if (!child.isActive()) {
                children.remove(i);
                removed++;
            } else {
                stack.push(child);
            }
        }
    }
    return removed;
}

