private void enlarge(final int size) {
    if (size <= 0) {
        return;
    }
    int currentCapacity = (buffer == null) ? 0 : buffer.length;
    int newCapacity = currentCapacity + size;
    // Ensure we grow at least twice the current capacity to reduce frequent reallocations
    if (newCapacity < currentCapacity * 2) {
        newCapacity = currentCapacity * 2;
    }
    // In case currentCapacity is 0 (buffer is null), just use the requested size
    if (currentCapacity == 0) {
        newCapacity = size;
    }
    byte[] newBuffer = new byte[newCapacity];
    if (buffer != null) {
        System.arraycopy(buffer, 0, newBuffer, 0, buffer.length);
    }
    buffer = newBuffer;
}

