    int newLen = length + byteLength;
    if (newLen > buffer.length) {
        int newCap = Math.max(buffer.length * 2, newLen);
        byte[] newBuf = new byte[newCap];
        System.arraycopy(buffer, 0, newBuf, 0, length);
        buffer = newBuf;
