public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 3) {
        return 3;
    }
    int candidate = desiredCapacity;
    // Ensure candidate is odd
    if ((candidate & 1) == 0) {
        candidate++;
    }
    while (candidate > 0) { // guard against overflow
        if (isPrime(candidate)) {
            return candidate;
        }
        // Skip even numbers
        candidate += 2;
    }
    // Fallback: return Integer.MAX_VALUE if overflow occurs
    return Integer.MAX_VALUE;
}

