        throw new IndexOutOfBoundsException();
    }
    int end = index + len;
    int i = index;
    int size = 0;
    while (i < end) {
        char ch = str.charAt(i);
        int cp;
        if (ch >= 0xD800 && ch <= 0xDBFF && i + 1 < end) {
            char ch2 = str.charAt(i + 1);
            if (ch2 >= 0xDC00 && ch2 <= 0xDFFF) {
                cp = ((ch - 0xD800) << 10) + (ch2 - 0xDC00) + 0x10000;
