public int readTag() throws IOException {
    int result = 0;
    int shift = 0;
    while (shift < 32) {
        int b = input.read();
        if (b == -1) {
            return 0; // EOF reached
        }
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result; // successfully read tag
        }
        shift += 7;
    }
    throw new IOException("Malformed varint");
}

